<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>WastedToken Mint — Challenge Coins</title>
<style>
  :root {
    --bg: #0a0b0e;
    --bg2: #12141a;
    --ink: #e8e4d9;
    --muted: #8a8678;
    --accent: #c4a35a;
    --line: #2a2d36;
    --card: #15171e;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body {
    font-family: Georgia, "Times New Roman", serif;
    background: var(--bg);
    color: var(--ink);
    min-height: 100vh;
    line-height: 1.55;
  }
  .noise {
    pointer-events: none;
    position: fixed; inset: 0; z-index: 9999; opacity: 0.035;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  }
  header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 1.25rem 2.5rem;
    border-bottom: 1px solid var(--line);
    background: rgba(10,11,14,0.92);
    position: sticky; top: 0; z-index: 50;
    backdrop-filter: blur(8px);
  }
  .brand {
    display: flex; align-items: baseline; gap: 0.65rem;
    letter-spacing: 0.04em;
  }
  .brand-mark {
    font-size: 0.7rem; text-transform: uppercase; color: var(--accent);
    letter-spacing: 0.22em; font-family: system-ui, sans-serif; font-weight: 600;
  }
  .brand-name {
    font-size: 1.15rem; font-weight: 400; color: var(--ink);
  }
  nav { display: flex; gap: 1.75rem; font-family: system-ui, sans-serif; font-size: 0.78rem; letter-spacing: 0.14em; text-transform: uppercase; }
  nav a { color: var(--muted); text-decoration: none; transition: color 0.2s; }
  nav a:hover { color: var(--accent); }

  .hero {
    display: grid;
    grid-template-columns: 1.1fr 0.9fr;
    gap: 2rem;
    align-items: center;
    padding: 3rem 2.5rem 4rem;
    min-height: calc(100vh - 64px);
    background:
      radial-gradient(ellipse 60% 50% at 35% 50%, rgba(196,163,90,0.08), transparent 70%),
      radial-gradient(ellipse 40% 40% at 70% 30%, rgba(80,100,140,0.06), transparent 60%),
      var(--bg);
  }
  .hero-copy h1 {
    font-size: clamp(2.4rem, 4.5vw, 3.8rem);
    font-weight: 400;
    line-height: 1.08;
    letter-spacing: -0.02em;
    margin-bottom: 1.25rem;
  }
  .hero-copy h1 em {
    font-style: italic; color: var(--accent);
  }
  .hero-copy .lede {
    font-family: system-ui, sans-serif;
    font-size: 1.02rem;
    color: var(--muted);
    max-width: 28rem;
    margin-bottom: 2rem;
    line-height: 1.7;
  }
  .hero-meta {
    display: flex; gap: 2rem; flex-wrap: wrap;
    font-family: system-ui, sans-serif; font-size: 0.72rem;
    letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted);
  }
  .hero-meta strong { display: block; color: var(--ink); font-size: 0.95rem; letter-spacing: 0.04em; margin-top: 0.3rem; text-transform: none; font-weight: 500; }

  .hero-stage {
    position: relative;
    display: flex; align-items: center; justify-content: center;
  }
  #coin-hero {
    width: min(480px, 90vw);
    height: min(480px, 90vw);
    display: block;
    border-radius: 50%;
    background: transparent;
  }
  .stage-ring {
    position: absolute;
    width: min(520px, 94vw);
    height: min(520px, 94vw);
    border-radius: 50%;
    border: 1px solid rgba(196,163,90,0.15);
    pointer-events: none;
  }
  .stage-ring::after {
    content: "";
    position: absolute; inset: 18px;
    border-radius: 50%;
    border: 1px dashed rgba(196,163,90,0.08);
  }

  section { padding: 4.5rem 2.5rem; }
  section .section-head {
    max-width: 40rem; margin-bottom: 2.5rem;
  }
  section h2 {
    font-size: 2rem; font-weight: 400; margin-bottom: 0.75rem;
    letter-spacing: -0.01em;
  }
  section .section-head p {
    font-family: system-ui, sans-serif; color: var(--muted); font-size: 0.95rem;
  }

  .about {
    background: var(--bg2);
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
