  .collection { max-width: 1100px; margin: 0 auto; }
  .editions {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
  }
  .edition {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 1.25rem 1rem 1.15rem;
    display: flex; flex-direction: column; align-items: center;
    position: relative;
    transition: border-color 0.25s, transform 0.25s;
  }
  .edition[data-state="available"]:hover {
    border-color: rgba(196,163,90,0.45);
    transform: translateY(-3px);
  }
  .edition[data-state="sold-out"] { opacity: 0.78; }
  .edition[data-state="coming-soon"] {
    border-color: rgba(100,120,160,0.35);
  }
  .edition-canvas {
    width: 160px; height: 160px;
    display: block; margin-bottom: 0.85rem;
  }
  .edition-label {
    font-family: system-ui, sans-serif;
    text-align: center; width: 100%;
  }
  .edition-label .name {
    font-size: 0.95rem; letter-spacing: 0.06em; text-transform: uppercase;
    margin-bottom: 0.25rem; color: var(--ink);
  }
  .edition-label .status {
    font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase;
    color: var(--muted); margin-bottom: 0.85rem; min-height: 1.1rem;
  }
  .edition[data-state="sold-out"] .status { color: #c45a5a; }
  .edition[data-state="coming-soon"] .status { color: #7a9cc4; }
  .edition .price {
    font-family: Georgia, serif; font-size: 1.15rem; color: var(--accent);
    margin-bottom: 0.75rem;
  }
  button.buy {
    font-family: system-ui, sans-serif;
    width: 100%;
    padding: 0.7rem 1rem;
    background: linear-gradient(180deg, #d4b56a, #a8843a);
    color: #1a1408;
    border: none; border-radius: 3px;
    font-size: 0.72rem; font-weight: 700;
    letter-spacing: 0.14em; text-transform: uppercase;
    cursor: pointer;
    transition: filter 0.2s, transform 0.15s;
  }
  button.buy:hover { filter: brightness(1.08); }
  button.buy:active { transform: scale(0.98); }
  .badge {
    position: absolute; top: 0.75rem; right: 0.75rem;
    font-family: system-ui, sans-serif;
    font-size: 0.58rem; letter-spacing: 0.14em; text-transform: uppercase;
    padding: 0.28rem 0.5rem; border-radius: 2px; font-weight: 700;
  }
  .edition[data-state="sold-out"] .badge {
    background: rgba(196,90,90,0.2); color: #e08080; border: 1px solid rgba(196,90,90,0.35);
  }
  .edition[data-state="coming-soon"] .badge {
    background: rgba(100,140,200,0.15); color: #9ab4d4; border: 1px solid rgba(100,140,200,0.3);
  }

  footer {
    border-top: 1px solid var(--line);
    padding: 2rem 2.5rem 2.5rem;
    display: flex; justify-content: space-between; align-items: center;
    font-family: system-ui, sans-serif; font-size: 0.75rem; color: var(--muted);
    letter-spacing: 0.06em;
  }
  footer .mark { color: var(--accent); }

  @media (max-width: 960px) {
    .hero { grid-template-columns: 1fr; text-align: center; padding-top: 2rem; }
    .hero-copy .lede { margin-left: auto; margin-right: auto; }
    .hero-meta { justify-content: center; }
    .about-grid { grid-template-columns: 1fr; }
    .editions { grid-template-columns: repeat(2, 1fr); }
    header { padding: 1rem 1.25rem; }
    section { padding: 3rem 1.25rem; }
  }
  @media (max-width: 520px) {
    .editions { grid-template-columns: 1fr; }
    nav { display: none; }
  }
</style>
</head>
