<script>
(function () {
  'use strict';

  // ---------- Math ----------
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function smoothstep(e0, e1, x) {
    var t = clamp((x - e0) / (e1 - e0), 0, 1);
    return t * t * (3 - 2 * t);
  }
  function rotX(p, a) {
    var c = Math.cos(a), s = Math.sin(a);
    return { x: p.x, y: p.y * c - p.z * s, z: p.y * s + p.z * c };
  }
  function rotY(p, a) {
    var c = Math.cos(a), s = Math.sin(a);
    return { x: p.x * c + p.z * s, y: p.y, z: -p.x * s + p.z * c };
  }
  function rotZ(p, a) {
    var c = Math.cos(a), s = Math.sin(a);
    return { x: p.x * c - p.y * s, y: p.x * s + p.y * c, z: p.z };
  }
  function normalize(v) {
    var l = Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z) || 1;
    return { x: v.x / l, y: v.y / l, z: v.z / l };
  }
  function dot(a, b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

  // ---------- Palette helpers ----------
  function hexToRgb(h) {
    return {
      r: parseInt(h.slice(1, 3), 16),
      g: parseInt(h.slice(3, 5), 16),
      b: parseInt(h.slice(5, 7), 16)
    };
  }
  function rgbStr(r, g, b, a) {
    if (a === undefined) return 'rgb(' + (r|0) + ',' + (g|0) + ',' + (b|0) + ')';
    return 'rgba(' + (r|0) + ',' + (g|0) + ',' + (b|0) + ',' + a + ')';
  }
  function shade(rgb, k) {
    return {
      r: clamp(rgb.r * k, 0, 255),
      g: clamp(rgb.g * k, 0, 255),
      b: clamp(rgb.b * k, 0, 255)
    };
  }
  function mix(a, b, t) {
    return {
      r: lerp(a.r, b.r, t),
      g: lerp(a.g, b.g, t),
      b: lerp(a.b, b.b, t)
    };
  }

  var METALS = {
    hero: {
      base: hexToRgb('#c9a84c'),
      dark: hexToRgb('#5a3e12'),
      mid: hexToRgb('#a8842e'),
      light: hexToRgb('#f0e0a0'),
      hilite: hexToRgb('#fff8e0'),
      edge: hexToRgb('#8a6a28')
    },
    bronze: {
      base: hexToRgb('#b87333'),
      dark: hexToRgb('#4a2a12'),
      mid: hexToRgb('#8a5520'),
      light: hexToRgb('#e0a868'),
      hilite: hexToRgb('#ffe0b0'),
      edge: hexToRgb('#6a4018')
    },
    silver: {
      base: hexToRgb('#c0c4c8'),
      dark: hexToRgb('#3a3e44'),
      mid: hexToRgb('#8a9098'),
      light: hexToRgb('#e8ecef'),
      hilite: hexToRgb('#ffffff'),
      edge: hexToRgb('#5a6068')
    },
    gold: {
      base: hexToRgb('#d4af37'),
      dark: hexToRgb('#5a4010'),
      mid: hexToRgb('#b8962a'),
      light: hexToRgb('#ffe680'),
      hilite: hexToRgb('#fff5c8'),
      edge: hexToRgb('#8a6a18')
    },
    black: {
      base: hexToRgb('#2a2c32'),
      dark: hexToRgb('#08090c'),
      mid: hexToRgb('#1a1c22'),
      light: hexToRgb('#5a6070'),
      hilite: hexToRgb('#a0a8b8'),
      edge: hexToRgb('#12141a')
    }
  };

  // ---------- Coin renderer ----------
  function project(p, cx, cy, scale, perspective) {
    var z = p.z;
    var f = perspective / (perspective + z);
    return { x: cx + p.x * scale * f, y: cy + p.y * scale * f, f: f, z: z };
  }

  function drawCoin(ctx, opts) {
    var W = opts.width;
    var H = opts.height;
    var cx = W * 0.5;
    var cy = H * 0.5;
    var t = opts.t; // 0..1
    var metal = opts.metal;
    var faceMode = opts.faceMode || 'both'; // both | front | back
    var radius = opts.radius || Math.min(W, H) * 0.32;
    var thick = opts.thick || radius * 0.14;
    var denomination = opts.denomination || '10,000';
    var showEmblemFront = opts.showEmblemFront !== false;

    // Clear backdrop — simple dark radial
    ctx.clearRect(0, 0, W, H);
    var bg = ctx.createRadialGradient(cx, cy, radius * 0.2, cx, cy, Math.max(W, H) * 0.55);
    bg.addColorStop(0, opts.bgInner || '#14161c');
    bg.addColorStop(0.55, opts.bgMid || '#0c0d11');
    bg.addColorStop(1, opts.bgOuter || '#08090c');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    // Soft ground shadow
    ctx.save();
    ctx.translate(cx, cy + radius * 0.85);
    ctx.scale(1, 0.22);
    var sh = ctx.createRadialGradient(0, 0, 1, 0, 0, radius * 1.1);
    sh.addColorStop(0, 'rgba(0,0,0,0.45)');
    sh.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = sh;
    ctx.beginPath();
    ctx.arc(0, 0, radius * 1.1, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // Animation: spin about Y and flip about X
    var rotYAngle = t * Math.PI * 2;
    var rotXAngle = t * Math.PI; // full flip so both faces visible
    // slight idle tilt so edge reeding reads better at t=0
    var baseTilt = -0.18;

    var light = normalize({ x: -0.45, y: -0.55, z: 0.7 });
    var perspective = radius * 6.5;
    var scale = 1;

    function xf(p) {
      var q = rotX(p, baseTilt + rotXAngle);
      q = rotY(q, rotYAngle);
      return q;
    }

    // Face normal after rotation
    var frontN = xf({ x: 0, y: 0, z: 1 });
    var backN = xf({ x: 0, y: 0, z: -1 });
    var frontFacing = frontN.z > 0;

    // Specular direction tracks light vs surface
    var halfV = normalize({ x: light.x, y: light.y, z: light.z + 1 });

    // --- Reeded edge ---
    var reeds = 72;
    var edgePts = [];
    for (var i = 0; i < reeds; i++) {
      var a0 = (i / reeds) * Math.PI * 2;
      var a1 = ((i + 1) / reeds) * Math.PI * 2;
      var ridge = (i % 2 === 0) ? 1.0 : 0.965;
      var pOuter0 = xf({ x: Math.cos(a0) * radius * ridge, y: Math.sin(a0) * radius * ridge, z: 0 });
      // sample front and back rim
      var pf0 = xf({ x: Math.cos(a0) * radius * ridge, y: Math.sin(a0) * radius * ridge, z: thick });
      var pb0 = xf({ x: Math.cos(a0) * radius * ridge, y: Math.sin(a0) * radius * ridge, z: -thick });
      var pf1 = xf({ x: Math.cos(a1) * radius * ridge, y: Math.sin(a1) * radius * ridge, z: thick });
      var pb1 = xf({ x: Math.cos(a1) * radius * ridge, y: Math.sin(a1) * radius * ridge, z: -thick });
      var mid = {
        x: (pf0.x + pb0.x + pf1.x + pb1.x) / 4,
        y: (pf0.y + pb0.y + pf1.y + pb1.y) / 4,
        z: (pf0.z + pb0.z + pf1.z + pb1.z) / 4
      };
      // outward normal approx
      var outward = normalize(xf({ x: Math.cos((a0 + a1) / 2), y: Math.sin((a0 + a1) / 2), z: 0 }));
      edgePts.push({ pf0: pf0, pb0: pb0, pf1: pf1, pb1: pb1, mid: mid, outward: outward, ridge: ridge, i: i });
    }
    edgePts.sort(function (a, b) { return a.mid.z - b.mid.z; });

    // Draw edge quads back-to-front
    for (var e = 0; e < edgePts.length; e++) {
      var seg = edgePts[e];
      // only draw if roughly side-on or slightly visible
      var nd = seg.outward.z;
      // skip fully occluded interior-facing
      var P0 = project(seg.pf0, cx, cy, scale, perspective);
      var P1 = project(seg.pb0, cx, cy, scale, perspective);
      var P2 = project(seg.pb1, cx, cy, scale, perspective);
      var P3 = project(seg.pf1, cx, cy, scale, perspective);

      var ndot = Math.max(0, dot(seg.outward, light));
      var spec = Math.pow(Math.max(0, dot(seg.outward, halfV)), 28);
      var ridgeShade = seg.ridge < 1 ? 0.72 : 1.0;
      var k = (0.22 + ndot * 0.75) * ridgeShade;
      k += spec * 0.85;
      // rim glint when edge faces camera
      var sideGlint = Math.pow(1 - Math.abs(seg.outward.z), 2) * 0.35;
      k += sideGlint;
      var col = mix(metal.dark, metal.light, clamp(k, 0, 1));
      if (spec > 0.35) col = mix(col, metal.hilite, (spec - 0.35) * 1.2);

      ctx.beginPath();
      ctx.moveTo(P0.x, P0.y);
      ctx.lineTo(P1.x, P1.y);
      ctx.lineTo(P2.x, P2.y);
      ctx.lineTo(P3.x, P3.y);
      ctx.closePath();
      ctx.fillStyle = rgbStr(col.r, col.g, col.b);
      ctx.fill();
    }

    // --- Faces ---
    function drawFace(isFront) {
      var zOff = isFront ? thick : -thick;
      var n = isFront ? frontN : backN;
      if (n.z <= 0.02) return; // not facing camera

      var segs = 96;
      var rim = [];
      for (var i = 0; i <= segs; i++) {
        var a = (i / segs) * Math.PI * 2;
        var p = xf({ x: Math.cos(a) * radius, y: Math.sin(a) * radius, z: zOff });
        rim.push(project(p, cx, cy, scale, perspective));
      }

      // Face disc path
      ctx.beginPath();
      ctx.moveTo(rim[0].x, rim[0].y);
      for (var i = 1; i < rim.length; i++) ctx.lineTo(rim[i].x, rim[i].y);
      ctx.closePath();

      // Base metallic radial, biased by light
      var ln = { x: light.x, y: light.y };
      // light position on face in screen space (approx)
      var faceCenter = project(xf({ x: 0, y: 0, z: zOff }), cx, cy, scale, perspective);
      // Specular rake: highlight center moves with rotation
      var hx = faceCenter.x + (-light.x * 0.55 + frontN.x * 0.3) * radius * 1.1;
      var hy = faceCenter.y + (-light.y * 0.55 + frontN.y * 0.3) * radius * 1.1;
      // Also rake with time so specular visibly travels
      var rake = t * Math.PI * 2;
      hx += Math.cos(rake * 1.0 + (isFront ? 0 : Math.PI)) * radius * 0.35;
      hy += Math.sin(rake * 0.7 + (isFront ? 0.5 : 2.0)) * radius * 0.25;

      var ndotL = Math.max(0, dot(n, light));
      var ambient = 0.28 + ndotL * 0.35;

      // Clip to coin
      ctx.save();
      ctx.clip();

      // Base fill
      var baseCol = mix(metal.dark, metal.base, ambient);
      ctx.fillStyle = rgbStr(baseCol.r, baseCol.g, baseCol.b);
      ctx.fillRect(0, 0, W, H);

      // Broad metal sheen
      var g1 = ctx.createRadialGradient(hx, hy, radius * 0.05, faceCenter.x, faceCenter.y, radius * 1.25);
      var c0 = metal.hilite;
      var c1 = metal.light;
      var c2 = metal.mid;
      var c3 = metal.dark;
      g1.addColorStop(0, rgbStr(c0.r, c0.g, c0.b, 0.95));
      g1.addColorStop(0.12, rgbStr(c1.r, c1.g, c1.b, 0.75));
      g1.addColorStop(0.35, rgbStr(c2.r, c2.g, c2.b, 0.55));
      g1.addColorStop(0.65, rgbStr(baseCol.r, baseCol.g, baseCol.b, 0.9));
      g1.addColorStop(1, rgbStr(c3.r, c3.g, c3.b, 1));
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = g1;
      ctx.fillRect(0, 0, W, H);

      // Secondary linear rake band
      var ang = rake + (isFront ? 0.4 : 2.2) + n.x * 2;
      ctx.save();
      ctx.translate(faceCenter.x, faceCenter.y);
      ctx.rotate(ang);
      var lg = ctx.createLinearGradient(-radius, 0, radius, 0);
      lg.addColorStop(0, 'rgba(0,0,0,0)');
      lg.addColorStop(0.35, rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.15));
      lg.addColorStop(0.48, rgbStr(metal.hilite.r, metal.hilite.g, metal.hilite.b, 0.55));
      lg.addColorStop(0.52, rgbStr(metal.hilite.r, metal.hilite.g, metal.hilite.b, 0.7));
      lg.addColorStop(0.58, rgbStr(metal.light.r, metal.light.g, metal.light.b, 0.25));
      lg.addColorStop(0.75, 'rgba(0,0,0,0)');
      lg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = lg;
      ctx.fillRect(-radius * 1.2, -radius * 1.2, radius * 2.4, radius * 2.4);
      ctx.restore();

      // Inner ring (proof-like border)
      function ellipseRing(rInner, rOuter, colA, colB) {
        ctx.beginPath();
        for (var i = 0; i <= segs; i++) {
          var a = (i / segs) * Math.PI * 2;
          var p = project(xf({ x: Math.cos(a) * rOuter, y: Math.sin(a) * rOuter, z: zOff }), cx, cy, scale, perspective);
          if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
        }
        ctx.closePath();
        // punch hole
        ctx.moveTo(
          project(xf({ x: rInner, y: 0, z: zOff }), cx, cy, scale, perspective).x,
          project(xf({ x: rInner, y: 0, z: zOff }), cx, cy, scale, perspective).y
        );
        for (var i = segs; i >= 0; i--) {
          var a = (i / segs) * Math.PI * 2;
          var p = project(xf({ x: Math.cos(a) * rInner, y: Math.sin(a) * rInner, z: zOff }), cx, cy, scale, perspective);
          ctx.lineTo(p.x, p.y);
        }
        ctx.closePath();
        var rg = ctx.createRadialGradient(hx, hy, 0, faceCenter.x, faceCenter.y, rOuter);
        rg.addColorStop(0, colA);
        rg.addColorStop(1, colB);
        ctx.fillStyle = rg;
        ctx.fill('evenodd');
      }

      // Raised outer rim band
      ctx.globalAlpha = 0.55;
      ellipseRing(radius * 0.88, radius * 0.98,
        rgbStr(metal.light.r, metal.light.g, metal.light.b, 0.5),
        rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.6));
      ctx.globalAlpha = 1;

      // Emboss lighting helper: draw path with highlight offset
      function embossPath(buildPath, depth) {
        depth = depth || 1.6;
        // shadow
        ctx.save();
        ctx.translate(depth * 0.9, depth * 1.1);
        buildPath();
        ctx.fillStyle = rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.55);
        ctx.fill();
        ctx.restore();
        // highlight
        ctx.save();
        ctx.translate(-depth * 0.7, -depth * 0.9);
        buildPath();
        ctx.fillStyle = rgbStr(metal.hilite.r, metal.hilite.g, metal.hilite.b, 0.4);
        ctx.fill();
        ctx.restore();
        // body
        buildPath();
        var eg = ctx.createLinearGradient(faceCenter.x - radius, faceCenter.y - radius, faceCenter.x + radius * 0.3, faceCenter.y + radius);
        eg.addColorStop(0, rgbStr(metal.light.r, metal.light.g, metal.light.b));
        eg.addColorStop(0.45, rgbStr(metal.base.r, metal.base.g, metal.base.b));
        eg.addColorStop(1, rgbStr(metal.dark.r, metal.dark.g, metal.dark.b));
        ctx.fillStyle = eg;
        ctx.fill();
      }

      function embossStroke(buildPath, lw, depth) {
        depth = depth || 1.2;
        ctx.save();
        ctx.translate(depth * 0.8, depth);
        buildPath();
        ctx.strokeStyle = rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.65);
        ctx.lineWidth = lw;
        ctx.stroke();
        ctx.restore();
        ctx.save();
        ctx.translate(-depth * 0.6, -depth * 0.8);
        buildPath();
        ctx.strokeStyle = rgbStr(metal.hilite.r, metal.hilite.g, metal.hilite.b, 0.45);
        ctx.lineWidth = lw * 0.85;
        ctx.stroke();
        ctx.restore();
        buildPath();
        ctx.strokeStyle = rgbStr(metal.mid.r, metal.mid.g, metal.mid.b, 0.95);
        ctx.lineWidth = lw;
        ctx.stroke();
      }

      // Transform 2d emblem coords (unit circle space) to screen via face
      function facePt(ux, uy, rScale) {
        rScale = rScale === undefined ? 1 : rScale;
        var p = xf({ x: ux * radius * rScale, y: uy * radius * rScale, z: zOff });
        return project(p, cx, cy, scale, perspective);
      }

      if (isFront && showEmblemFront) {
        // ===== FRONT: WastedToken emblem =====
        // Laurel / ring
        embossStroke(function () {
          ctx.beginPath();
          for (var i = 0; i <= 64; i++) {
            var a = (i / 64) * Math.PI * 2;
            var rr = 0.72;
            var p = facePt(Math.cos(a) * rr, Math.sin(a) * rr);
            if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
          }
          ctx.closePath();
        }, 2.4, 1.5);

        embossStroke(function () {
          ctx.beginPath();
          for (var i = 0; i <= 64; i++) {
            var a = (i / 64) * Math.PI * 2;
            var rr = 0.62;
            var p = facePt(Math.cos(a) * rr, Math.sin(a) * rr);
            if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
          }
          ctx.closePath();
        }, 1.3, 1.0);

        // Central WT monogram shield
        embossPath(function () {
          var top = facePt(0, -0.38);
          var bl = facePt(-0.28, -0.05);
          var br = facePt(0.28, -0.05);
          var bot = facePt(0, 0.42);
          var ml = facePt(-0.28, 0.18);
          var mr = facePt(0.28, 0.18);
          ctx.beginPath();
          ctx.moveTo(top.x, top.y);
          ctx.lineTo(br.x, br.y);
          ctx.lineTo(mr.x, mr.y);
          ctx.quadraticCurveTo(facePt(0.22, 0.32).x, facePt(0.22, 0.32).y, bot.x, bot.y);
          ctx.quadraticCurveTo(facePt(-0.22, 0.32).x, facePt(-0.22, 0.32).y, ml.x, ml.y);
          ctx.lineTo(bl.x, bl.y);
          ctx.closePath();
        }, 2.0);

        // W letter (raised)
        embossStroke(function () {
          var pts = [
            [-0.16, -0.12], [-0.10, 0.18], [-0.05, 0.02],
            [0, 0.18], [0.05, 0.02], [0.10, 0.18], [0.16, -0.12]
          ];
          ctx.beginPath();
          for (var i = 0; i < pts.length; i++) {
            var p = facePt(pts[i][0], pts[i][1]);
            if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
          }
        }, 2.8, 1.6);

        // Token diamond above
        embossPath(function () {
          var p0 = facePt(0, -0.52);
          var p1 = facePt(0.1, -0.42);
          var p2 = facePt(0, -0.32);
          var p3 = facePt(-0.1, -0.42);
          ctx.beginPath();
          ctx.moveTo(p0.x, p0.y);
          ctx.lineTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.lineTo(p3.x, p3.y);
          ctx.closePath();
        }, 1.4);

        // Laurel leaves left/right
        function leaf(side, k) {
          var baseA = side * (0.9 + k * 0.22);
          var uy = 0.15 + k * 0.18;
          embossPath(function () {
            var root = facePt(Math.cos(baseA) * 0.48, Math.sin(baseA) * 0.48 * 0.3 + uy * 0.5 - 0.15);
            var tip = facePt(Math.cos(baseA) * 0.68, Math.sin(baseA) * 0.2 + uy - 0.2);
            var c1 = facePt(Math.cos(baseA - 0.15 * side) * 0.58, Math.sin(baseA) * 0.15 + uy * 0.7 - 0.18);
            var c2 = facePt(Math.cos(baseA + 0.12 * side) * 0.58, Math.sin(baseA) * 0.15 + uy * 0.8 - 0.12);
            ctx.beginPath();
            ctx.moveTo(root.x, root.y);
            ctx.quadraticCurveTo(c1.x, c1.y, tip.x, tip.y);
            ctx.quadraticCurveTo(c2.x, c2.y, root.x, root.y);
          }, 1.0);
        }
        for (var L = 0; L < 5; L++) {
          leaf(-1, L);
          leaf(1, L);
        }

        // Micro text along bottom arc "WASTEDTOKEN MINT"
        ctx.save();
        ctx.font = 'bold ' + Math.max(8, radius * 0.075) + 'px system-ui,sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        var label = 'WASTEDTOKEN MINT';
        for (var ci = 0; ci < label.length; ci++) {
          var frac = (ci / (label.length - 1)) - 0.5;
          var ang = Math.PI * 0.5 + frac * 1.6;
          var rr = 0.82;
          var p = facePt(Math.cos(ang) * rr, Math.sin(ang) * rr * 0.95);
          // approximate tangent rotation from neighboring points
          var p2 = facePt(Math.cos(ang + 0.05) * rr, Math.sin(ang + 0.05) * rr * 0.95);
          var rot = Math.atan2(p2.y - p.y, p2.x - p.x);
          ctx.save();
          ctx.translate(p.x, p.y);
          ctx.rotate(rot);
          ctx.fillStyle = rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.55);
          ctx.fillText(label[ci], 0.6, 0.6);
          ctx.fillStyle = rgbStr(metal.light.r, metal.light.g, metal.light.b, 0.85);
          ctx.fillText(label[ci], 0, 0);
          ctx.restore();
        }
        ctx.restore();

      } else if (!isFront) {
        // ===== BACK: denomination =====
        // Concentric guides
        embossStroke(function () {
          ctx.beginPath();
          for (var i = 0; i <= 64; i++) {
            var a = (i / 64) * Math.PI * 2;
            var p = facePt(Math.cos(a) * 0.78, Math.sin(a) * 0.78);
            if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
          }
          ctx.closePath();
        }, 1.8, 1.3);

        // Inner circle
        embossStroke(function () {
          ctx.beginPath();
          for (var i = 0; i <= 48; i++) {
            var a = (i / 48) * Math.PI * 2;
            var p = facePt(Math.cos(a) * 0.5, Math.sin(a) * 0.5);
            if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
          }
          ctx.closePath();
        }, 1.2, 1.0);

        // Big number
        var num = denomination;
        ctx.save();
        // Because face may be mirrored when viewing back after Y rot, we draw in face space via center
        var center = facePt(0, -0.06);
        var right = facePt(0.2, -0.06);
        var up = facePt(0, -0.26);
        var scaleX = Math.sqrt((right.x - center.x) * (right.x - center.x) + (right.y - center.y) * (right.y - center.y)) / 0.2;
        var angFace = Math.atan2(right.y - center.y, right.x - center.x);
        // Detect back-face horizontal flip from cross of axes
        var upA = Math.atan2(up.y - center.y, up.x - center.x);
        var cross = Math.sin(angFace - upA);
        var flipY = cross > 0 ? 1 : -1;

        ctx.translate(center.x, center.y);
        ctx.rotate(angFace);
        ctx.scale(scaleX / radius, flipY * scaleX / radius);

        function drawNum(ox, oy, col, blur) {
          ctx.fillStyle = col;
          if (blur) { ctx.shadowColor = col; ctx.shadowBlur = blur; }
          ctx.font = '700 ' + (radius * 0.28) + 'px Georgia,serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillText(num, ox, oy);
          ctx.shadowBlur = 0;
        }
        drawNum(1.5, 2, rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.7), 0);
        drawNum(-1.2, -1.5, rgbStr(metal.hilite.r, metal.hilite.g, metal.hilite.b, 0.45), 0);
        drawNum(0, 0, rgbStr(metal.light.r, metal.light.g, metal.light.b, 0.95), 0);

        ctx.font = '600 ' + (radius * 0.11) + 'px system-ui,sans-serif';
        ctx.letterSpacing = '0.2em';
        ctx.fillStyle = rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.65);
        ctx.fillText('TOKENS', 1, radius * 0.22 + 1);
        ctx.fillStyle = rgbStr(metal.light.r, metal.light.g, metal.light.b, 0.9);
        ctx.fillText('TOKENS', 0, radius * 0.22);

        // small mint mark
        ctx.font = '600 ' + (radius * 0.065) + 'px system-ui,sans-serif';
        ctx.fillStyle = rgbStr(metal.mid.r, metal.mid.g, metal.mid.b, 0.9);
        ctx.fillText('WTM', 0, radius * 0.38);
        ctx.restore();

        // Radial tick marks
        for (var ti = 0; ti < 36; ti++) {
          var a = (ti / 36) * Math.PI * 2;
          var long = ti % 3 === 0;
          var p0 = facePt(Math.cos(a) * (long ? 0.84 : 0.86), Math.sin(a) * (long ? 0.84 : 0.86));
          var p1 = facePt(Math.cos(a) * 0.92, Math.sin(a) * 0.92);
          ctx.beginPath();
          ctx.moveTo(p0.x, p0.y);
          ctx.lineTo(p1.x, p1.y);
          ctx.strokeStyle = rgbStr(metal.light.r, metal.light.g, metal.light.b, long ? 0.55 : 0.3);
          ctx.lineWidth = long ? 1.6 : 1;
          ctx.stroke();
          // emboss shadow line
          ctx.beginPath();
          ctx.moveTo(p0.x + 0.6, p0.y + 0.6);
          ctx.lineTo(p1.x + 0.6, p1.y + 0.6);
          ctx.strokeStyle = rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.35);
          ctx.stroke();
        }
      }

      // Sharp specular hotspot that rakes
      var specStrength = Math.pow(Math.max(0, dot(n, halfV)), 12);
      var sg = ctx.createRadialGradient(hx, hy, 0, hx, hy, radius * (0.35 + 0.2 * (1 - specStrength)));
      sg.addColorStop(0, rgbStr(255, 255, 250, 0.55 + specStrength * 0.4));
      sg.addColorStop(0.25, rgbStr(metal.hilite.r, metal.hilite.g, metal.hilite.b, 0.25 + specStrength * 0.25));
      sg.addColorStop(0.55, rgbStr(metal.light.r, metal.light.g, metal.light.b, 0.06));
      sg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = sg;
      ctx.beginPath();
      ctx.arc(hx, hy, radius * 0.7, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';

      // Rim darken for depth
      var rimG = ctx.createRadialGradient(faceCenter.x, faceCenter.y, radius * 0.72, faceCenter.x, faceCenter.y, radius * 1.02);
      rimG.addColorStop(0, 'rgba(0,0,0,0)');
      rimG.addColorStop(0.7, 'rgba(0,0,0,0)');
      rimG.addColorStop(1, rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.55));
      ctx.fillStyle = rimG;
      ctx.fillRect(0, 0, W, H);

      ctx.restore(); // clip

      // Outer silhouette edge stroke
      ctx.beginPath();
      ctx.moveTo(rim[0].x, rim[0].y);
      for (var i = 1; i < rim.length; i++) ctx.lineTo(rim[i].x, rim[i].y);
      ctx.closePath();
      ctx.strokeStyle = rgbStr(metal.dark.r, metal.dark.g, metal.dark.b, 0.8);
      ctx.lineWidth = 1.25;
      ctx.stroke();
      // bright rim catchlight
      ctx.strokeStyle = rgbStr(metal.hilite.r, metal.hilite.g, metal.hilite.b, 0.25 + ndotL * 0.25);
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    // Draw order: farther face first (if any visible edges), then near face
    // With thickness, only the facing face is filled; edge already drawn.
    if (frontFacing) {
      if (backN.z > 0.02) drawFace(false);
      drawFace(true);
    } else {
      if (frontN.z > 0.02) drawFace(true);
      drawFace(false);
    }

    // Ambient occlusion contact under coin (subtle)
    // already have shadow
  }

  // ---------- Hero ----------
  var heroCanvas = document.getElementById('coin-hero');
  var heroCtx = heroCanvas.getContext('2d');
  var animTime = 0;
  var playing = true;
  var raf = null;
  var lastTs = 0;
  var LOOP_MS = 6000;

  function renderHero(t) {
    t = ((t % 1) + 1) % 1;
    animTime = t;
    drawCoin(heroCtx, {
      width: heroCanvas.width,
      height: heroCanvas.height,
      t: t,
      metal: METALS.hero,
      radius: heroCanvas.width * 0.30,
      thick: heroCanvas.width * 0.30 * 0.13,
      denomination: '10,000',
      bgInner: '#161820',
      bgMid: '#0c0d12',
      bgOuter: '#07080b'
    });
  }

  function tick(ts) {
    if (!playing) return;
    if (!lastTs) lastTs = ts;
    var dt = ts - lastTs;
    lastTs = ts;
    animTime = (animTime + dt / LOOP_MS) % 1;
    renderHero(animTime);
    raf = requestAnimationFrame(tick);
  }

  renderHero(0);
  raf = requestAnimationFrame(tick);

  window.demo = {
    canvas: heroCanvas,
    setTime: function (t) {
      t = Number(t);
      if (!isFinite(t)) t = 0;
      t = clamp(t, 0, 1);
      renderHero(t);
    },
    pause: function () {
      playing = false;
      if (raf) { cancelAnimationFrame(raf); raf = null; }
      lastTs = 0;
    }
  };

  // ---------- Edition tiles ----------
  var editionConfigs = {
    bronze: { metal: METALS.bronze, denom: '2,500', t: 0.08 },
    silver: { metal: METALS.silver, denom: '10,000', t: 0.12 },
    gold: { metal: METALS.gold, denom: '50,000', t: 0.18 },
    black: { metal: METALS.black, denom: '100,000', t: 0.22 }
  };

  var tiles = document.querySelectorAll('.edition');
  for (var i = 0; i < tiles.length; i++) {
    (function (tile) {
      var key = tile.getAttribute('data-edition');
      var cfg = editionConfigs[key];
      var canvas = tile.querySelector('.edition-canvas');
      var ctx = canvas.getContext('2d');
      var state = tile.getAttribute('data-state');

      function paint(tt) {
        drawCoin(ctx, {
          width: canvas.width,
          height: canvas.height,
          t: tt,
          metal: cfg.metal,
          radius: canvas.width * 0.30,
          thick: canvas.width * 0.30 * 0.13,
          denomination: cfg.denom,
          bgInner: '#1a1c24',
          bgMid: '#12141a',
          bgOuter: '#0e1016'
        });
        if (state === 'sold-out') {
          ctx.save();
          ctx.fillStyle = 'rgba(20,10,10,0.35)';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.translate(canvas.width / 2, canvas.height / 2);
          ctx.rotate(-0.4);
          ctx.font = '700 18px system-ui,sans-serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillStyle = 'rgba(220,100,100,0.85)';
          ctx.strokeStyle = 'rgba(40,10,10,0.5)';
          ctx.lineWidth = 3;
          ctx.strokeText('SOLD OUT', 0, 0);
          ctx.fillText('SOLD OUT', 0, 0);
          ctx.restore();
        }
      }

      paint(cfg.t);

      // gentle idle for available / coming-soon
      if (state !== 'sold-out') {
        var localT = cfg.t;
        var base = cfg.t;
        function idle(ts) {
          localT = base + Math.sin(ts * 0.0006 + base * 10) * 0.04;
          paint(((localT % 1) + 1) % 1);
          requestAnimationFrame(idle);
        }
        requestAnimationFrame(idle);
      }

      var btn = tile.querySelector('button.buy');
      if (btn) {
        btn.addEventListener('click', function () {
          btn.textContent = 'Added ✓';
          btn.style.filter = 'brightness(0.9)';
          setTimeout(function () {
            btn.textContent = 'Add to cart';
            btn.style.filter = '';
          }, 1400);
        });
      }
    })(tiles[i]);
